"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import styles from "./Tooltip.module.css";
import { cn } from "@/lib/utils";

export type TooltipProps = {
  children: ReactNode;
  content: ReactNode;
  placement?: "bottom" | "top";
  interactive?: boolean;
  maxWidth?: number;
  /** Applied to the portaled bubble, without changing the trigger. */
  className?: string;
  /** Layout of the wrapper around the trigger. */
  triggerClassName?: string;
};

export function Tooltip({
  children,
  content,
  placement = "bottom",
  interactive = false,
  maxWidth,
  className,
  triggerClassName,
}: TooltipProps) {
  const id = useId();
  const anchor = useRef<HTMLSpanElement>(null);
  const bubble = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const focusOpened = useRef(false);
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState<{ left: number; top: number }>();
  const cancelClose = () => clearTimeout(timer.current);
  const close = () => {
    cancelClose();
    setOpen(false);
  };
  const show = () => {
    cancelClose();
    setOpen(true);
  };
  const leave = () => {
    cancelClose();
    timer.current = setTimeout(() => {
      if (
        !anchor.current?.contains(document.activeElement) &&
        !bubble.current?.contains(document.activeElement)
      )
        setOpen(false);
    }, 120);
  };
  const blur = (event: React.FocusEvent<HTMLElement>) => {
    if (
      anchor.current?.contains(event.relatedTarget) ||
      (interactive && bubble.current?.contains(event.relatedTarget))
    )
      return;
    focusOpened.current = false;
    close();
  };
  useEffect(() => () => clearTimeout(timer.current), []);
  useLayoutEffect(() => {
    if (!open) return;
    const reposition = () => {
      const trigger = anchor.current?.firstElementChild;
      if (!trigger || !bubble.current) return;
      const rect = trigger.getBoundingClientRect();
      const tip = bubble.current.getBoundingClientRect();
      const below = window.innerHeight - rect.bottom - 8;
      const above = rect.top - 8;
      const topPreferred =
        placement === "top"
          ? above >= tip.height || above > below
          : below < tip.height && above > below;
      setPosition({
        left: Math.max(
          10,
          Math.min(
            rect.left + rect.width / 2 - tip.width / 2,
            window.innerWidth - tip.width - 10,
          ),
        ),
        top: Math.max(
          10,
          Math.min(
            topPreferred ? rect.top - tip.height - 8 : rect.bottom + 8,
            window.innerHeight - tip.height - 10,
          ),
        ),
      });
    };
    reposition();
    const observer = new ResizeObserver(reposition);
    if (bubble.current) observer.observe(bubble.current);
    // Ancestor menu entrances and trigger hover transforms move the anchor
    // without resizing it or producing a scroll event.
    document.addEventListener("animationend", reposition, true);
    document.addEventListener("transitionend", reposition, true);
    window.addEventListener("resize", reposition);
    window.addEventListener("scroll", reposition, true);
    return () => {
      observer.disconnect();
      document.removeEventListener("animationend", reposition, true);
      document.removeEventListener("transitionend", reposition, true);
      window.removeEventListener("resize", reposition);
      window.removeEventListener("scroll", reposition, true);
    };
  }, [open, placement]);
  useEffect(() => {
    if (!open) return;
    const outside = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        !anchor.current?.contains(event.target) &&
        !bubble.current?.contains(event.target)
      ) {
        setOpen(false);
        focusOpened.current = false;
      }
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        if (bubble.current?.contains(document.activeElement))
          (anchor.current?.firstElementChild as HTMLElement)?.focus();
        setOpen(false);
        focusOpened.current = false;
      }
    };
    document.addEventListener("pointerdown", outside);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", outside);
      document.removeEventListener("keydown", escape);
    };
  }, [open]);
  // The trigger may arrive as a Server Component slot. Update its DOM attributes
  // rather than cloning an unresolved React element across that boundary.
  useLayoutEffect(() => {
    const trigger = anchor.current?.firstElementChild;
    if (!(trigger instanceof HTMLElement)) return;
    const description = trigger.getAttribute("aria-describedby");
    const expanded = trigger.getAttribute("aria-expanded");
    const expandable = trigger.tagName === "BUTTON" || expanded !== null;
    if (open)
      trigger.setAttribute(
        "aria-describedby",
        [description, id].filter(Boolean).join(" "),
      );
    if (expandable) trigger.setAttribute("aria-expanded", String(open));
    return () => {
      if (description === null) trigger.removeAttribute("aria-describedby");
      else trigger.setAttribute("aria-describedby", description);
      if (expanded === null) trigger.removeAttribute("aria-expanded");
      else trigger.setAttribute("aria-expanded", expanded);
    };
  }, [open, id]);

  return (
    <>
      <span
        ref={anchor}
        className={cn("inline-flex align-middle min-w-0", triggerClassName)}
        onPointerEnter={(event) => {
          // Touch generates compatibility mouse events before click. Treat only
          // hovering pointers as hover so the first tap opens the tooltip.
          if (event.pointerType !== "touch") show();
        }}
        onMouseLeave={leave}
        onFocus={() => {
          focusOpened.current = !open;
          show();
        }}
        onBlur={blur}
        onClick={() => {
          cancelClose();
          if (focusOpened.current) {
            focusOpened.current = false;
            setOpen(true);
          } else setOpen((value) => !value);
        }}
        onKeyDown=[REDACTED_SECRET]
          if (interactive && event.key === "Tab" && !event.shiftKey && open) {
            const link = bubble.current?.querySelector<HTMLElement>(
              "a[href], button:not([disabled]), [tabindex='0']",
            );
            if (link) {
              event.preventDefault();
              link.focus();
            }
          }
        }}
      >
        {children}
      </span>
      {open &&
        createPortal(
          <div
            ref={bubble}
            id={id}
            role="tooltip"
            className={[
              `${styles.bubble} fixed z-[1000] box-border w-max max-w-[min(310px,_calc(100vw_-_20px))] max-h-[calc(100dvh_-_20px)] overflow-y-auto py-3 px-3.5 rounded-[14px] [background:var(--card)] text-foreground [border:1px_solid_var(--color-tooltip-border-3)] shadow-[0_14px_40px_var(--color-tooltip-box-shadow-4)] [font-family:var(--font-plus-jakarta),_sans-serif] text-[13px] leading-normal wrap-anywhere`,
              className,
            ]
              .filter(Boolean)
              .join(" ")}
            style={{
              maxWidth: maxWidth
                ? `min(${maxWidth}px, calc(100vw - 20px))`
                : undefined,
              left: position?.left ?? 10,
              top: position?.top ?? 10,
              visibility: position ? "visible" : "hidden",
            }}
            onMouseEnter={cancelClose}
            onMouseLeave={leave}
            onBlur={blur}
            onKeyDown=[REDACTED_SECRET]
              if (
                event.key === "Tab" &&
                event.shiftKey &&
                event.target ===
                  bubble.current?.querySelector(
                    "a[href], button, [tabindex='0']",
                  )
              ) {
                event.preventDefault();
                (anchor.current?.firstElementChild as HTMLElement)?.focus();
              }
            }}
          >
            {content}
          </div>,
          document.getElementById("main-content") ?? document.body,
        )}
    </>
  );
}
